"use strict";
import { useCallback, useState } from "react";
import { useAccount } from "hooks/useAccount";
import { useWeb3React } from "@web3-react/core";
import { useMutation } from "@tanstack/react-query";
import { stargateClient } from "api/stargate";
import { logger } from "utilities/src/logger/logger";
import { useEip5792Support } from "uniswap/src/features/transactions/swap/contexts/hooks/useEip5792Support";
import { useChainId } from "wagmi";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
const CURRENT_SEND_CALLS_VERSION = "2.0.0";
async function sendBatchTransactions(provider, transactions, from, chainId) {
  const calls = transactions.map((tx) => ({
    to: tx.to,
    data: tx.data,
    value: tx.value
  }));
  const chainIdHex = `0x${chainId.toString(16)}`;
  const result = await provider.send("wallet_sendCalls", [
    {
      version: CURRENT_SEND_CALLS_VERSION,
      calls,
      from,
      chainId: chainIdHex,
      atomicRequired: true
    }
  ]);
  return result.id;
}
async function pollBatchStatus(provider, batchId, maxAttempts = 60) {
  for (let i = 0; i < maxAttempts; i++) {
    try {
      const status = await provider.send("wallet_getCallsStatus", [batchId]);
      if (status.status === "CONFIRMED") {
        return { success: true, receipts: status.receipts };
      }
      if (status.status === "FAILED") {
        throw new Error("Batch transaction failed");
      }
      await new Promise((resolve) => setTimeout(resolve, 2e3));
    } catch (error) {
      if (i === maxAttempts - 1) {
        throw error;
      }
    }
  }
  throw new Error("Batch transaction timeout");
}
export function useBridgeTransaction() {
  const account = useAccount();
  const { provider } = useWeb3React();
  const chainId = useChainId();
  const supportsEip5792 = useEip5792Support(chainId);
  const [txState, setTxState] = useState({ status: "idle" });
  const executeBridgeMutation = useMutation({
    mutationFn: async (quote) => {
      if (!account.connector || !account.address) {
        throw new Error("Wallet not connected");
      }
      if (!quote.transactions || quote.transactions.length === 0) {
        throw new Error("No transactions to execute");
      }
      const connectorProvider = await account.connector.getProvider();
      if (!connectorProvider) {
        throw new Error("Could not get provider from connector");
      }
      setTxState({ status: "pending" });
      const txHashes = [];
      if (supportsEip5792 && quote.transactions.length > 1) {
        try {
          logger.info("Using EIP-5792 wallet transaction batching", {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { transactionCount: quote.transactions.length, chainId }
          });
          const batchId = await sendBatchTransactions(connectorProvider, quote.transactions, account.address, chainId);
          setTxState({
            status: "confirming",
            txHash: batchId
          });
          logger.info("Batch transaction sent, waiting for confirmation", {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { batchId }
          });
          const result = await pollBatchStatus(connectorProvider, batchId);
          logger.info("Batch transaction confirmed", {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { batchId, receipts: result.receipts }
          });
          popupRegistry.addPopup(
            {
              type: PopupType.Transaction,
              hash: batchId
            },
            batchId
          );
          return {
            txHashes: [batchId],
            srcChainKey: quote.srcChainKey,
            dstChainKey: quote.dstChainKey
          };
        } catch (error) {
          logger.warn("Batch transaction failed, falling back to sequential", {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { error }
          });
        }
      }
      for (const transaction of quote.transactions) {
        try {
          const value = transaction.value || "0";
          const valueHex = value.startsWith("0x") ? value : `0x${BigInt(value).toString(16)}`;
          const txHash = await connectorProvider.request({
            method: "eth_sendTransaction",
            params: [{
              from: account.address,
              to: transaction.to,
              data: transaction.data,
              value: valueHex
            }]
          });
          txHashes.push(txHash);
          setTxState({
            status: "confirming",
            txHash
          });
          logger.info("Bridge transaction sent", {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { txHash }
          });
          popupRegistry.addPopup(
            {
              type: PopupType.Transaction,
              hash: txHash
            },
            txHash
          );
        } catch (error) {
          logger.error(error instanceof Error ? error : new Error("Unknown transaction error"), {
            tags: { file: "useBridgeTransaction", function: "executeBridgeMutation" },
            extra: { transaction, error: String(error) }
          });
          throw error;
        }
      }
      return {
        txHashes,
        srcChainKey: quote.srcChainKey,
        dstChainKey: quote.dstChainKey
      };
    },
    onSuccess: (data) => {
      setTxState({
        status: "success",
        txHash: data.txHashes[0]
      });
    },
    onError: (error) => {
      setTxState({
        status: "error",
        error
      });
    }
  });
  const executeBridge = useCallback(
    async (quote) => {
      try {
        await executeBridgeMutation.mutateAsync(quote);
      } catch (error) {
        logger.error(error instanceof Error ? error : new Error("Bridge execution failed"), {
          tags: { file: "useBridgeTransaction", function: "executeBridge" }
        });
      }
    },
    [executeBridgeMutation]
  );
  const resetState = useCallback(() => {
    setTxState({ status: "idle" });
  }, []);
  return {
    executeBridge,
    txState,
    resetState,
    isLoading: executeBridgeMutation.isPending
  };
}
export function useBridgeStatus(txHash, srcChainId) {
  return useMutation({
    mutationFn: async () => {
      if (!txHash || !srcChainId) {
        throw new Error("Missing transaction hash or chain ID");
      }
      const response = await stargateClient.getBridgeStatus(txHash, srcChainId);
      if (!response.success) {
        throw new Error(response.message || "Failed to fetch bridge status");
      }
      return response;
    }
  });
}
