"use strict";
import { Trans } from "react-i18next";
import { useCallback, useMemo, useState } from "react";
import styled from "styled-components";
import { Button } from "ui/src";
import { useAccountDrawer } from "components/AccountDrawer/MiniPortfolio/hooks";
import { AutoColumn } from "components/deprecated/Column";
import { ArrowWrapper, PageWrapper } from "components/swap/styled";
import { useAccount } from "hooks/useAccount";
import { useProviderChainId } from "hooks/useProviderChainId";
import { useTokenBalance } from "hooks/useTokenBalance";
import { ArrowDown } from "react-feather";
import { useDisconnect } from "wagmi";
import { useStargateQuote } from "./hooks/useStargateQuote";
import { useStargateChains } from "./hooks/useStargateChains";
import { useStargateTokens } from "./hooks/useStargateTokens";
import { useBridgeTransaction } from "./hooks/useBridgeTransaction";
import { BridgeDetails } from "./components/BridgeDetails";
import { ChainTokenSelector } from "./components/ChainTokenSelector";
import { parseUnits } from "ethers/lib/utils";
import ConnectWalletLanding from "components/ConnectWalletLanding";
const BridgeContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
`;
const ArrowContainer = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
`;
const AmountInput = styled.div`
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 16px;
  background: ${({ theme }) => theme.surface2};
  border-radius: 12px;
`;
const InputLabel = styled.label`
  font-size: 14px;
  color: ${({ theme }) => theme.neutral2};
  font-weight: 500;
`;
const BalanceRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
`;
const BalanceText = styled.span`
  font-size: 12px;
  color: ${({ theme }) => theme.neutral2};
`;
const MaxButton = styled.button`
  background: ${({ theme }) => theme.accent2};
  color: ${({ theme }) => theme.accent1};
  border: none;
  border-radius: 8px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;

  &:hover {
    opacity: 0.8;
  }

  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;
const SeeBalanceButton = styled.button`
  background: transparent;
  color: ${({ theme }) => theme.accent1};
  border: 1px solid ${({ theme }) => theme.accent1};
  border-radius: 8px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: ${({ theme }) => theme.accent2};
  }
`;
const StyledButton = styled(Button)`
  ${({ $isDisabled }) => $isDisabled && `
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
  `}
`;
const InputRow = styled.div`
  display: flex;
  flex-direction: column;
  gap: 4px;
`;
const StyledInput = styled.input`
  background: transparent;
  border: none;
  outline: none;
  font-size: ${({ $hasError }) => $hasError ? "14px" : "28px"};
  font-weight: 500;
  color: ${({ theme, $hasError }) => $hasError ? theme.critical : theme.neutral1};
  width: 100%;

  &::placeholder {
    color: ${({ theme }) => theme.neutral3};
  }

  &:disabled {
    color: ${({ theme, $hasError }) => $hasError ? theme.critical : theme.neutral2};
  }
`;
const UsdValue = styled.div`
  font-size: 14px;
  color: ${({ theme }) => theme.neutral2};
  font-weight: 500;
`;
const BridgeWrapper = styled.div`
  position: relative;
  background: ${({ theme }) => theme.surface1};
  border-radius: 16px;
  padding: 8px;
  width: 100%;
  max-width: 480px;
`;
export function BridgeForm() {
  const account = useAccount();
  const accountDrawer = useAccountDrawer();
  const { chainId: detectedChainId } = useProviderChainId();
  const { disconnect } = useDisconnect();
  const [inputAmount, setInputAmount] = useState("");
  const [sourceChain, setSourceChain] = useState(null);
  const [destChain, setDestChain] = useState(null);
  const [sourceToken, setSourceToken] = useState(null);
  const [destToken, setDestToken] = useState(null);
  const { executeBridge, isLoading: isBridgeLoading } = useBridgeTransaction();
  const { data: chainsData, isLoading: chainsLoading } = useStargateChains();
  const { balance: sourceTokenBalance, isLoading: isBalanceLoading } = useTokenBalance({
    tokenAddress: sourceToken?.address,
    decimals: sourceToken?.decimals || 18,
    chainId: sourceChain?.chainId,
    enabled: !!(sourceToken && sourceChain && detectedChainId === sourceChain.chainId)
  });
  const { data: allTokensData } = useStargateTokens({
    enabled: true
  });
  const destTokens = useMemo(() => {
    if (!sourceToken || !sourceChain || !allTokensData?.tokens) {
      return [];
    }
    return allTokensData.tokens.filter(
      (token) => token.symbol === sourceToken.symbol && token.chainKey !== sourceChain.chainKey
    );
  }, [sourceToken, sourceChain, allTokensData]);
  const PLACEHOLDER_ADDRESS = "0x0000000000000000000000000000000000000001";
  const quoteRequest = useMemo(() => {
    if (!inputAmount || !sourceChain || !destChain || !sourceToken || !destToken) {
      return null;
    }
    try {
      const amountInWei = parseUnits(inputAmount, sourceToken.decimals).toString();
      return {
        srcChainKey: sourceChain.chainKey,
        srcChainId: sourceChain.chainId,
        srcTokenAddress: sourceToken.address,
        dstChainKey: destChain.chainKey,
        dstChainId: destChain.chainId,
        dstTokenAddress: destToken.address,
        amountIn: amountInWei,
        sender: account.address || PLACEHOLDER_ADDRESS,
        slippage: 50
        // 0.5%
      };
    } catch {
      return null;
    }
  }, [account.address, inputAmount, sourceChain, destChain, sourceToken, destToken]);
  const { data: quoteData, isLoading: quoteLoading, error: quoteError } = useStargateQuote({
    request: quoteRequest,
    enabled: !!quoteRequest
  });
  const handleSwitchChains = useCallback(() => {
    setSourceChain(destChain);
    setDestChain(sourceChain);
    setSourceToken(destToken);
    setDestToken(sourceToken);
  }, [sourceChain, destChain, sourceToken, destToken]);
  const handleSourceSelect = useCallback((chain, token) => {
    setSourceChain(chain);
    setSourceToken(token);
    setDestChain(null);
    setDestToken(null);
  }, []);
  const handleDestSelect = useCallback((chain, token) => {
    setDestChain(chain);
    setDestToken(token);
  }, []);
  const isQuoteValid = quoteData && !quoteError;
  const errorMessage = useMemo(() => {
    if (!quoteError) return null;
    if (quoteError instanceof Error) {
      let msg = quoteError.message;
      msg = msg.replace(/^HTTP \d+:\s*/i, "");
      return msg;
    }
    return "Failed to get bridge quote";
  }, [quoteError]);
  const inputUsdValue = useMemo(() => {
    if (!inputAmount || !sourceToken?.price?.usd) return null;
    const amount = parseFloat(inputAmount);
    if (isNaN(amount)) return null;
    return amount * sourceToken.price.usd;
  }, [inputAmount, sourceToken]);
  const outputUsdValue = useMemo(() => {
    if (!quoteData || !destToken?.price?.usd) return null;
    const amount = Number(quoteData.amountOut) / Math.pow(10, destToken.decimals);
    return amount * destToken.price.usd;
  }, [quoteData, destToken]);
  const needsChainSwitch = useMemo(() => {
    return sourceChain && detectedChainId !== sourceChain.chainId;
  }, [sourceChain, detectedChainId]);
  const isNativeToken = useMemo(() => {
    if (!sourceToken?.address) return false;
    const addr = sourceToken.address.toLowerCase();
    return addr === "0x0000000000000000000000000000000000000000" || addr === "0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";
  }, [sourceToken]);
  const handleSwitchToSourceChain = useCallback(async () => {
    if (!sourceChain || !account.connector) return;
    try {
      const provider = await account.connector.getProvider();
      const targetChainIdHex = `0x${sourceChain.chainId.toString(16)}`;
      try {
        await provider.request({
          method: "wallet_switchEthereumChain",
          params: [{ chainId: targetChainIdHex }]
        });
      } catch (switchError) {
        if (switchError.code === 4902 || switchError.code === -32603) {
          if (sourceChain.rpcUrls && sourceChain.rpcUrls.length > 0) {
            await provider.request({
              method: "wallet_addEthereumChain",
              params: [{
                chainId: targetChainIdHex,
                chainName: sourceChain.name,
                nativeCurrency: {
                  name: sourceChain.nativeCurrency?.name || "ETH",
                  symbol: sourceChain.nativeCurrency?.symbol || "ETH",
                  decimals: sourceChain.nativeCurrency?.decimals || 18
                },
                rpcUrls: sourceChain.rpcUrls,
                blockExplorerUrls: sourceChain.blockExplorerUrls || []
              }]
            });
          } else {
            throw new Error("Chain not in wallet and no RPC URL available");
          }
        } else {
          throw switchError;
        }
      }
    } catch (error) {
      console.error("Failed to switch/add chain:", error);
    }
  }, [sourceChain, account.connector]);
  const handleBridge = useCallback(async () => {
    if (!quoteData) return;
    await executeBridge(quoteData);
    setInputAmount("");
  }, [quoteData, executeBridge]);
  const handleMaxClick = useCallback(() => {
    if (!sourceTokenBalance) return;
    if (isNativeToken) {
      const GAS_RESERVE = 5e-3;
      const balance = parseFloat(sourceTokenBalance);
      if (balance > GAS_RESERVE) {
        setInputAmount((balance - GAS_RESERVE).toString());
      } else {
        setInputAmount(sourceTokenBalance);
      }
    } else {
      setInputAmount(sourceTokenBalance);
    }
  }, [sourceTokenBalance, isNativeToken]);
  const isAbstractWallet = account.connector?.id === "xyz.abs.privy" || account.connector?.name === "Abstract";
  if (isAbstractWallet) {
    return <PageWrapper>
        <ConnectWalletLanding
      title="Multi-chain wallet required"
      description="Abstract Global Wallet only supports Abstract chain. Please connect with a multi-chain wallet like MetaMask or WalletConnect to use the bridge."
      buttonText="Disconnect"
      onButtonClick={() => disconnect()}
    />
      </PageWrapper>;
  }
  return <>
    <PageWrapper>
      <BridgeWrapper>
        <BridgeContainer>
          <AutoColumn gap="md">
            <ChainTokenSelector
    label="From"
    selectedChain={sourceChain}
    selectedToken={sourceToken}
    chains={chainsData?.chains || []}
    tokens={allTokensData?.tokens || []}
    onSelect={handleSourceSelect}
  />

            <AmountInput>
              <BalanceRow>
                <InputLabel>
                  <Trans>You send</Trans>
                </InputLabel>
                {sourceToken && sourceChain && (needsChainSwitch ? <SeeBalanceButton onClick={handleSwitchToSourceChain}>
                      <Trans>Show balance</Trans>
                    </SeeBalanceButton> : sourceTokenBalance ? <BalanceText>
                      Balance: {parseFloat(sourceTokenBalance).toFixed(6)} {sourceToken.symbol}
                    </BalanceText> : null)}
              </BalanceRow>
              <InputRow>
                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                  <StyledInput
    type="text"
    inputMode="decimal"
    autoComplete="off"
    autoCorrect="off"
    placeholder="0.0"
    value={inputAmount}
    onChange={(e) => setInputAmount(e.target.value)}
    style={{ flex: 1 }}
  />
                  {sourceTokenBalance && !needsChainSwitch && <MaxButton onClick={handleMaxClick} disabled={!sourceTokenBalance}>
                      MAX
                    </MaxButton>}
                </div>
                {inputUsdValue !== null && <UsdValue>~${inputUsdValue.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</UsdValue>}
              </InputRow>
            </AmountInput>

            <ArrowWrapper clickable onClick={handleSwitchChains}>
              <ArrowContainer>
                <ArrowDown size="16" color="currentColor" />
              </ArrowContainer>
            </ArrowWrapper>

            <ChainTokenSelector
    label="To"
    selectedChain={destChain}
    selectedToken={destToken}
    chains={chainsData?.chains || []}
    tokens={destTokens}
    onSelect={handleDestSelect}
    disabled={!sourceToken}
  />

            <AmountInput>
              <InputLabel>
                <Trans>You receive</Trans>
              </InputLabel>
              <InputRow>
                <StyledInput
    type="text"
    value={errorMessage ? errorMessage : quoteData && destToken ? (Number(quoteData.amountOut) / Math.pow(10, destToken.decimals)).toFixed(6) : ""}
    disabled
    readOnly
    $hasError={!!errorMessage}
  />
                {outputUsdValue !== null && !errorMessage && <UsdValue>~${outputUsdValue.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</UsdValue>}
              </InputRow>
            </AmountInput>

            {quoteData && <BridgeDetails quote={quoteData} />}

            <StyledButton
    theme="primary"
    onPress={!account.address ? () => accountDrawer.open() : needsChainSwitch ? handleSwitchToSourceChain : handleBridge}
    disabled={account.address && (quoteError || !needsChainSwitch && (!isQuoteValid || quoteLoading || isBridgeLoading))}
    $isDisabled={account.address && (!!quoteError || !needsChainSwitch && (!isQuoteValid || quoteLoading || isBridgeLoading))}
  >
              {!account.address ? <Trans>Connect wallet</Trans> : quoteError ? <Trans>Quote error</Trans> : needsChainSwitch ? `Switch to ${sourceChain?.name}` : isBridgeLoading ? <Trans>Bridging...</Trans> : quoteLoading ? <Trans>Fetching quote...</Trans> : !isQuoteValid ? <Trans>Enter amount</Trans> : <Trans>Bridge tokens</Trans>}
            </StyledButton>
          </AutoColumn>
        </BridgeContainer>
      </BridgeWrapper>
    </PageWrapper>
    </>;
}
