"use strict";
import { useQuery } from "@tanstack/react-query";
import { stargateClient } from "api/stargate";
export function useStargateTokens({ srcChainKey, srcToken, enabled = true } = {}) {
  return useQuery({
    queryKey: ["stargate-tokens", srcChainKey, srcToken],
    queryFn: async () => {
      const response = await stargateClient.getTokens(srcChainKey, srcToken);
      if (!response.success) {
        throw new Error(response.message || "Failed to fetch tokens");
      }
      return response;
    },
    enabled,
    staleTime: 5 * 60 * 1e3,
    // 5 minutes
    gcTime: 10 * 60 * 1e3,
    // 10 minutes
    retry: 3
  });
}
