const getTokenIconUrl = (symbol) => {
  const iconSymbol = symbol.toLowerCase().replace("usdc.e", "usdc").replace(".e", "");
  return `https://icons-ckg.pages.dev/stargate-light/tokens/${iconSymbol}.svg`;
};
const getChainIconUrl = (chainKey) => {
  return `https://icons-ckg.pages.dev/stargate-light/networks/${chainKey.toLowerCase()}.svg`;
};
export function ChainTokenSelector({
  label,
  selectedChain,
  selectedToken,
  chains,
  tokens,
  onSelect,
  disabled = false
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [displayCount, setDisplayCount] = useState(50);
  const searchInputRef = useRef(null);
  const tokenListRef = useRef(null);
  const sortedChains = useMemo(() => {
    return [...chains].sort((a, b) => {
      if (a.name === "Abstract") return -1;
      if (b.name === "Abstract") return 1;
      if (a.name === "Ethereum") return -1;
      if (b.name === "Ethereum") return 1;
      return a.name.localeCompare(b.name);
    });
  }, [chains]);
  const [selectedChainKey, setSelectedChainKey] = useState("all");
  const filteredTokens = useMemo(() => {
    let filteredTokens2 = tokens;
    if (selectedChainKey !== "all") {
      filteredTokens2 = filteredTokens2.filter((token) => token.chainKey === selectedChainKey);
    }
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filteredTokens2 = filteredTokens2.filter(
        (token) => token.symbol.toLowerCase().includes(query) || token.name.toLowerCase().includes(query) || token.address.toLowerCase().includes(query)
      );
    }
    return filteredTokens2;
  }, [tokens, selectedChainKey, searchQuery]);
  const handleTokenSelect = (token) => {
    const chain = chains.find((c) => c.chainKey === token.chainKey);
    if (chain) {
      onSelect(chain, token);
      setIsOpen(false);
      setSearchQuery("");
    }
  };
  const handleOpen = () => {
    if (disabled) return;
    setIsOpen(true);
    setSelectedChainKey("all");
    setDisplayCount(50);
    setTimeout(() => searchInputRef.current?.focus(), 100);
  };
  const handleClose = () => {
    setIsOpen(false);
    setSearchQuery("");
    setDisplayCount(50);
  };
  const handleScroll = useCallback(() => {
    const container = tokenListRef.current;
    if (!container) return;
    const scrollPosition = container.scrollTop + container.clientHeight;
    const scrollHeight = container.scrollHeight;
    if (scrollPosition >= scrollHeight * 0.8 && displayCount < filteredTokens.length) {
      setDisplayCount((prev) => Math.min(prev + 30, filteredTokens.length));
    }
  }, [displayCount, filteredTokens.length]);
  useEffect(() => {
    const container = tokenListRef.current;
    if (!container) return;
    container.addEventListener("scroll", handleScroll);
    return () => container.removeEventListener("scroll", handleScroll);
  }, [handleScroll]);
  useEffect(() => {
    setDisplayCount(50);
  }, [selectedChainKey, searchQuery]);
  return <>
      <SelectorButton onClick={handleOpen} disabled={disabled} style={{ opacity: disabled ? 0.5 : 1, cursor: disabled ? "not-allowed" : "pointer" }}>
        <SelectorContent>
          <Label>{label}</Label>
          {selectedChain && selectedToken ? <SelectedInfo>
              <SelectedTokenIconContainer>
                <SelectedTokenIcon
    src={getTokenIconUrl(selectedToken.symbol)}
    alt={selectedToken.symbol}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  />
                <SelectedChainBadge
    src={getChainIconUrl(selectedChain.chainKey)}
    alt={selectedChain.name}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  />
              </SelectedTokenIconContainer>
              <SelectedDetails>
                <SelectedTokenName>{selectedToken.symbol}</SelectedTokenName>
                <SelectedChainName>{selectedChain.name}</SelectedChainName>
              </SelectedDetails>
            </SelectedInfo> : <Placeholder>
              <Trans>Select chain and token</Trans>
            </Placeholder>}
        </SelectorContent>
        <ChevronDown size={20} />
      </SelectorButton>

      <Modal
    name={ModalName.CurrencySearch}
    isModalOpen={isOpen}
    onClose={handleClose}
    maxWidth={480}
  >
        <ModalContainer>
          {
    /* Search */
  }
          <SearchContainer>
            <SearchIcon>
              <Search size={16} />
            </SearchIcon>
            <SearchInput
    ref={searchInputRef}
    type="text"
    placeholder="Search by name or address..."
    value={searchQuery}
    onChange={(e) => setSearchQuery(e.target.value)}
  />
          </SearchContainer>

          {
    /* Chain List (Horizontal Bar) */
  }
          <ChainList>
            {
    /* All chains option */
  }
            <ChainItem
    isActive={selectedChainKey === "all"}
    onClick={() => setSelectedChainKey("all")}
    title="All Chains"
  >
              <ChainName isActive={selectedChainKey === "all"}>All</ChainName>
            </ChainItem>

            {sortedChains.map((chain) => <ChainItem
    key={chain.chainKey}
    isActive={selectedChainKey === chain.chainKey}
    onClick={() => setSelectedChainKey(chain.chainKey)}
    title={chain.name}
  >
                <ChainIcon
    src={getChainIconUrl(chain.chainKey)}
    alt={chain.name}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  />
              </ChainItem>)}
          </ChainList>

          {
    /* Token List */
  }
          <TokenList ref={tokenListRef}>
            {filteredTokens.length > 0 ? <>
                {filteredTokens.slice(0, displayCount).map((token) => <TokenItem key={`${token.chainKey}-${token.address}`} onClick={() => handleTokenSelect(token)}>
                    <TokenInfo>
                      <TokenIconContainer>
                        <TokenIcon
    src={getTokenIconUrl(token.symbol)}
    alt={token.symbol}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  />
                        <ChainBadge
    src={getChainIconUrl(token.chainKey)}
    alt={chains.find((c) => c.chainKey === token.chainKey)?.name || token.chainKey}
    onError={(e) => {
      e.currentTarget.style.display = "none";
    }}
  />
                      </TokenIconContainer>
                      <TokenDetails>
                        <TokenName>{token.symbol}</TokenName>
                        <TokenSymbol>{chains.find((c) => c.chainKey === token.chainKey)?.name || token.chainKey}</TokenSymbol>
                      </TokenDetails>
                    </TokenInfo>
                    {token.price?.usd && <TokenPrice>${token.price.usd.toFixed(2)}</TokenPrice>}
                  </TokenItem>)}
                {displayCount < filteredTokens.length && <NoResults>
                    <Trans>Scroll for more tokens ({displayCount} of {filteredTokens.length})</Trans>
                  </NoResults>}
              </> : <NoResults>
                <Trans>No tokens found</Trans>
              </NoResults>}
          </TokenList>
        </ModalContainer>
      </Modal>
    </>;
}
