"use strict";
import { useEffect, useState } from "react";
import { formatUnits } from "ethers/lib/utils";
import { useAccount } from "./useAccount";
export function useTokenBalance({
  tokenAddress,
  decimals,
  chainId,
  enabled = true
}) {
  const account = useAccount();
  const [balance, setBalance] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  useEffect(() => {
    if (!enabled || !account.address || !tokenAddress || !chainId || !account.connector) {
      setBalance(null);
      setIsLoading(false);
      return;
    }
    let isCancelled = false;
    const fetchBalance = async () => {
      try {
        setIsLoading(true);
        const provider = await account.connector.getProvider();
        if (!provider) {
          setBalance(null);
          setIsLoading(false);
          return;
        }
        const currentChainId = provider.chainId ? parseInt(provider.chainId, 16) : null;
        if (currentChainId !== chainId) {
          setBalance(null);
          setIsLoading(false);
          return;
        }
        const isNativeToken = tokenAddress.toLowerCase() === "0x0000000000000000000000000000000000000000" || tokenAddress.toLowerCase() === "0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee";
        if (isNativeToken) {
          const balance2 = await provider.request({
            method: "eth_getBalance",
            params: [account.address, "latest"]
          });
          if (!isCancelled) {
            const formatted = formatUnits(balance2, decimals);
            setBalance(formatted);
            setIsLoading(false);
          }
        } else {
          const data = `0x70a08231000000000000000000000000${account.address.slice(2).toLowerCase()}`;
          const balance2 = await provider.request({
            method: "eth_call",
            params: [
              {
                to: tokenAddress,
                data
              },
              "latest"
            ]
          });
          if (!isCancelled) {
            const formatted = formatUnits(balance2, decimals);
            setBalance(formatted);
            setIsLoading(false);
          }
        }
      } catch (error) {
        console.error("Error fetching token balance:", error);
        if (!isCancelled) {
          setBalance(null);
          setIsLoading(false);
        }
      }
    };
    fetchBalance();
    const interval = setInterval(fetchBalance, 1e4);
    return () => {
      isCancelled = true;
      clearInterval(interval);
    };
  }, [account.address, account.connector, tokenAddress, decimals, chainId, enabled]);
  return {
    balance,
    isLoading
  };
}
